/** Disposable developed-world checkpoint; genuine desk packets, purchases,
 * collection, proposal/confirmation, live ritual and renderer captures.
 * Not an uninterrupted acquisition-to-conversion automation acceptance run. */
public final class TycoonExpansionVisualCheck {
    private static Minecraft mc;private static volatile int stage,age;private static int ticks;private static volatile boolean pending;private static volatile Throwable failed;private static UUID resident,actor,automatedResident;private static int oldScale,beforePower;private static BlockPos farm;private static long farmIncomeBefore;
    public static void tick(){
        mc=Minecraft.getInstance();mc.options.pauseOnLostFocus=false;if(failed!=null)throw new IllegalStateException("Expansion QA stage="+stage,failed);if(mc.player==null||mc.getSingleplayerServer()==null||mc.player.tickCount<80)return;
        age++;if(++ticks>12000||age>(stage==32?3000:900))throw new IllegalStateException("Expansion QA timeout at "+stage);if(ticks%100==0)com.mojang.logging.LogUtils.getLogger().info("TYCOON_EXPANSION stage={} age={} screen={}",stage,age,mc.screen==null?"none":mc.screen.getClass().getSimpleName());
        switch(stage){
            case 0->{mc.getWindow().setWindowed(1280,960);mc.options.guiScale().set(2);mc.resizeDisplay();server(0,p->{setup(p);go(1);});}
            case 1->{if(age>60&&world())go(2);}
            case 2->{if(age>20){check(press("Automation"),"Automation entry missing");go(3);}}
            case 3->{if(age>20&&mc.screen instanceof com.coraline.client.TycoonAutomationScreen){layout();shot("workers_hiring");server(3,p->{beforePower=TycoonShop.count(p,TycoonContent.VOID_POWER.get());go(4);});}}
            case 4->{if(age>10){check(press("Hire —"),"Hire action missing");go(5);}}
            case 5->server(5,p->{var all=TycoonWorkers.workers(TycoonWorld.home(p));if(all.size()!=1)return;var row=all.getCompound(all.getAllKeys().iterator().next());check(row.getBoolean("Break")&&row.getInt("Unlocked")==1&&TycoonShop.count(p,TycoonContent.VOID_POWER.get())==beforePower-TycoonAutomationConfig.PRICES.get("overworld_maid").get(),"Hire did not charge real Power/start on break");go(6);});
            case 6->{if(age>20){check(press("Manage hired"),"Worker management missing");go(7);}}
            case 7->{if(age>20){layout();shot("worker_model_salary_and_policies");check(press("Unlock next"),"Upgrade action missing");go(8);}}
            case 8->server(8,p->{var all=TycoonWorkers.workers(TycoonWorld.home(p));if(all.getCompound(all.getAllKeys().iterator().next()).getInt("Unlocked")==2)go(9);});
            case 9->{if(age>20){check(press("Operating Level"),"Operating level missing");go(10);}}
            case 10->server(10,p->{var all=TycoonWorkers.workers(TycoonWorld.home(p));if(all.getCompound(all.getAllKeys().iterator().next()).getInt("Operating")==2)go(11);});
            case 11->{if(age>20){check(press("Market"),"Market tab missing");go(12);}}
            case 12->{if(age>25){layout();shot("actual_fictional_market_history");check(press("Buy shares"),"Actual trade action missing");go(13);}}
            case 13->server(13,p->{var h=TycoonWorld.home(p);if(h.state.getCompound("Shares").isEmpty())return;check(h.state.getList("TradeHistory",10).size()==1,"Actual trade did not commit once");go(14);});
            case 14->{if(age>20){check(press("Resources")||press("Stock"),"Resources tab missing");go(15);}}
            case 15->{if(age>20){layout();shot("produced_resources_collection");check(press("Collect selected"),"Collect selected control missing");go(16);}}
            case 16->server(16,p->{if(TycoonShop.count(p,Items.IRON_INGOT)==0)return;check(TycoonMachines.producedCount(TycoonWorld.home(p))==0,"Collection failed to debit actual stored output");go(17);});
            case 17->{if(age>15){oldScale=mc.options.guiScale().get();mc.options.guiScale().set(4);mc.resizeDisplay();go(18);}}
            case 18->{if(age>20){layout();shot("small_window_scrollable_controls");mc.screen.mouseScrolled(mc.screen.width/2.,mc.screen.height/2.,-5);go(19);}}
            case 19->{if(age>20){layout();shot("small_window_scrolled_controls");mc.options.guiScale().set(oldScale);mc.resizeDisplay();mc.setScreen(null);server(19,p->{var child=(TycoonNpc)p.serverLevel().getEntity(actor);check(child!=null,"Ready visitor lost");var r=TycoonWorld.home(p).residents.get(resident);check(!r.n.getBoolean("KnowsSoulFarm"),"Visitor legitimately discovered the farm; checkpoint layout is unsafe");TycoonDialogue.set(r,1,.1);p.teleportTo(p.serverLevel(),child.getX()+1.5,child.getY(),child.getZ()+1.5,135,0);go(20);});}}
            case 20->{if(age>25){var child=clientActor();if(child!=null){mc.gameMode.interact(mc.player,child,InteractionHand.MAIN_HAND);go(21);}}}
            case 21->{if(age>20&&mc.screen instanceof com.coraline.client.TycoonConversationScreen){layout();shot("proposal_condition_unconfirmed");mc.options.guiScale().set(4);mc.resizeDisplay();layout();shot("small_window_dialogue_choices");check(press(">"),"Small dialogue choices are not paginated");layout();mc.options.guiScale().set(oldScale);mc.resizeDisplay();check(press("Would you like"),"Proposal explanation missing");go(22);}}
            case 22->{if(age>20){check(press("Confirm: stay"),"Explicit confirmation missing");mc.setScreen(null);go(23);}}
            case 23->{if(age>40)mc.setScreen(null);if(age==60)shot("live_button_eye_thread_ritual");if(age>180)server(23,p->{var h=TycoonWorld.home(p);var r=h.residents.get(resident);if(r.n.contains("ConversionRitual")&&age<500)return;check(r.n.getString("Status").equals("CONVERTED")&&TycoonSouls.collection(h).size()==3&&p.serverLevel().getEntity(actor)==null,"Normal confirmation did not retire exactly one resident/create one soul: "+r.n.getString("Status")+" trust="+TycoonDialogue.trust(r)+" ritual="+r.n.getCompound("ConversionRitual"));p.teleportTo(p.serverLevel(),farm.getX()+.5,farm.getY()+1,farm.getZ()-3.5,0,8);go(24);});}
            case 24->{if(age>50){shot("distinct_souls_inside_physical_farm");server(24,p->{var c=TycoonWorld.home(p).center();p.teleportTo(p.serverLevel(),c.getX()+24,c.getY()+2,c.getZ()-3,0,13);go(25);});}}
            case 25->{if(age>40){shot("physical_theatre_performer");server(25,p->{var c=TycoonWorld.home(p).center();p.teleportTo(p.serverLevel(),c.getX()+1,c.getY(),c.getZ()+1,180,0);go(26);});}}
            case 26->{if(age>40&&world()){press("Souls");go(27);}}
            case 27->{if(age>25){shot("soul_collection_and_farm_management");server(27,p->{try{check(TycoonCheckpoints.home(p)&&TycoonCheckpoints.player(p),"Final home/player checkpoint mismatch");}catch(java.io.IOException e){throw new IllegalStateException(e);}go(28);});}}
            case 28->{if(age>20){mc.setScreen(null);server(28,p->{seeingStoneScene(p);go(29);});}}
            case 29->{if(age>60){mc.options.setCameraType(net.minecraft.client.CameraType.FIRST_PERSON);mc.player.getInventory().selected=0;mc.options.keyUse.setDown(true);if(!mc.player.isUsingItem())mc.gameMode.useItem(mc.player,InteractionHand.MAIN_HAND);if(age>100&&com.coraline.client.SeeingStoneClient.raised()){shot("overworld_stone_hostile_and_passive");server(29,p->{p.setXRot(-55);p.connection.teleport(p.getX(),p.getY(),p.getZ(),p.getYRot(),-55);go(30);});}}}
            case 30->{if(age>40){shot("seeing_stone_sky_and_hand");mc.options.keyUse.setDown(false);mc.gameMode.releaseUsingItem(mc.player);go(31);}}
            case 31->{if(age>30){check(!com.coraline.client.SeeingStoneClient.raised(),"Releasing the stone did not restore normal view");shot("seeing_stone_released_normal_sky");server(31,p->{automationScene(p);go(32);});}}
            case 32->{if(age==150)shot("autonomous_manager_real_conversation");server(32,p->{var h=TycoonWorld.home(p);var r=h.residents.get(automatedResident);if(age%200==0)com.mojang.logging.LogUtils.getLogger().info("AUTOMATION_CHAIN status={} talks={} trust={} visit={} workers={}",r.n.getString("Status"),r.n.getInt("Conversations"),TycoonDialogue.trust(r),r.n.getCompound("Visit").getString("Phase"),TycoonWorkers.projection(h));if(!r.n.getString("Status").equals("CONVERTED"))return;var soul=TycoonSouls.collection(h).getCompound(r.n.getUUID("SoulId").toString());if(!soul.hasUUID("Farm")||TycoonSoulFarms.farms(h).getCompound(soul.getUUID("Farm").toString()).getLong("RateMicros")<=0)return;check(r.n.getInt("Conversations")>=2&&r.n.getList("ProposalMemories",10).size()==1&&TycoonSouls.collection(h).size()==4,"Automated conversation/conversion identity failure");check(TycoonSoulFarms.farms(h).getCompound(soul.getUUID("Farm").toString()).getLong("LastProducedClock")>farmIncomeBefore,"Assigned soul has not entered real production");check(TycoonWorkers.workers(h).getAllKeys().stream().map(k->TycoonWorkers.workers(h).getCompound(k)).filter(w->w.getString("Type").equals("other_manager")||w.getString("Type").equals("soul_manager")).allMatch(w->w.getLong("SalaryPaid")>0),"Automation ran without salary");go(33);});}
            case 33->{if(age>20){shot("automated_conversion_assignment_and_production");server(33,p->{try{check(TycoonCheckpoints.home(p)&&TycoonCheckpoints.player(p),"Automation checkpoint failed");}catch(java.io.IOException e){throw new IllegalStateException(e);}com.mojang.logging.LogUtils.getLogger().info("TYCOON_EXPANSION_NATIVE_COMPLETE: declared eight developed plots, sky, two structures, two initial souls, farm, funded balance, ready visitor and later mature .96-trust visitor/level5 staff checkpoint; genuine desk hire/upgrade/operating-level/trade/resource collection and proposal packets, two unique conversions, normal/small-window layout, actual world/ritual/farm/theatre/Overworld Seeing Stone captures; connected paid managers autonomously earned remaining trust through real conversations, proposed/confirmed, converted, assigned and produced with saved receipts; not new-placement-to-maturity, multiplayer, restart or power-loss acceptance");go(34);});}}
            case 34->{if(age>20)mc.stop();}
        }
    }
    private static void setup(ServerPlayer p){
        p.server.getPlayerList().op(p.getGameProfile());p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);p.getInventory().clearContent();for(int i=10;i<18;i++)p.getInventory().setItem(i,new ItemStack(TycoonContent.VOID_POWER.get(),64));var h=TycoonWorld.home(p);h.state.putBoolean("Activated",true);h.state.putLong("ActiveTicks",1000);h.state.putLong("SoulEssence",5000);check(TycoonWorld.prepare(p),"Declared core blocked");TycoonWorld.enter(p);var l=p.serverLevel();var c=h.center();
        for(int[] tile:new int[][]{{1,0},{0,1},{-2,0},{1,1},{2,0},{2,1},{0,2},{1,2}}){var cells=new LinkedHashMap<BlockPos,net.minecraft.world.level.block.state.BlockState>();for(int x=0;x<16;x++)for(int z=0;z<16;z++){var at=c.offset(tile[0]*16+x,-1,tile[1]*16+z);cells.put(at,Blocks.GRASS_BLOCK.defaultBlockState());for(int y=1;y<=7;y++)cells.put(at.above(y),Blocks.AIR.defaultBlockState());}place(l,cells);var record=TycoonLandscape.encode(cells,c.offset(tile[0]*16,0,tile[1]*16));record.putInt("Tier",2);var terrain=h.state.getCompound("Terrain");terrain.put(TycoonLandscape.key(tile[0],tile[1]),record);h.state.put("Terrain",terrain);}
        var attractions=new CompoundTag();for(var type:List.of(TycoonAttractionType.THEATRE,TycoonAttractionType.GARDEN)){var at=c.offset(type==TycoonAttractionType.THEATRE?24:8,-1,type==TycoonAttractionType.THEATRE?8:24);var row=new CompoundTag();var id=UUID.randomUUID();row.putUUID("Id",id);row.putString("Type",type.id());row.putLong("Position",at.asLong());row.putInt("Tier",3);row.putBoolean("Operational",true);row.put("Branches",new CompoundTag());var plan=TycoonAttractionPlan.create(type,at,0,3,new CompoundTag());place(l,plan);row.put("Generated",TycoonLandscape.encode(plan,at));attractions.put(id.toString(),row);}h.state.put("Attractions",attractions);
        farm=c.offset(-24,-1,8);var f=new CompoundTag();var farmId=UUID.randomUUID();f.putUUID("Id",farmId);f.putUUID("Owner",h.owner);f.putLong("Position",farm.asLong());f.putInt("Tier",3);f.putInt("Ordinal",1);var farmPlan=TycoonSoulFarmPlan.create(farm,0,3);place(l,farmPlan);f.put("Generated",TycoonLandscape.encode(farmPlan,farm));var farms=new CompoundTag();farms.put(farmId.toString(),f);h.state.put("SoulFarms",farms);var souls=new CompoundTag();for(int i=0;i<2;i++){var soul=TycoonSouls.derive(h,TycoonCare.generate(UUID.randomUUID()),UUID.randomUUID());soul.putUUID("Farm",farmId);souls.put(soul.getUUID("Id").toString(),soul);}h.state.put("Souls",souls);
        // A genuine paid sky plus eight declared plots keep passive
        // goodness positive. Readiness is an explicit checkpoint at stage19,
        // not a claim that the menu test earned Trustness while buying stock.
        check(TycoonSkies.select(p,5).startsWith("Purchased"),"Paid QA sky purchase refused");
        var output=new CompoundTag();output.putLong("minecraft:iron_ingot",160);h.state.put("ProducedResources",output);for(int i=0;i<120;i++)TycoonMarket.get(p.server).advance();TycoonLandscape.recalculate(h);
        var r=TycoonCare.generate(UUID.randomUUID());resident=r.id;r.n.putString("Status","ACTIVE");r.n.putBoolean("DebugChild",true);r.n.putInt("VisitCount",2);r.n.putBoolean("RelationshipInitialized",true);r.n.putLong("NextRequest",1000000);r.n.putLong("NextIncident",1000000);TycoonDialogue.set(r,1,.1);var visit=new CompoundTag();visit.putUUID("Session",UUID.randomUUID());visit.putString("Phase","INSIDE");visit.putLong("EnteredAt",h.clock());visit.putLong("LeaveAfter",h.clock()+20000);visit.putLong("LastSeen",h.clock());visit.putString("LastDimension",TycoonWorld.KEY.location().toString());visit.putLong("LastAt",c.asLong());r.n.put("Visit",visit);h.residents.put(r.id,r);var child=TycoonContent.NPC.get().create(l);child.configure(h.owner,r.id,false,r.n.getInt("Appearance"));child.setPos(Vec3.atBottomCenterOf(c.offset(2,0,2)));actor=child.getUUID();r.n.putUUID("Entity",actor);l.addFreshEntity(child);TycoonVisitTickets.world(p,c);h.state.putBoolean("VisitActive",true);TycoonWorld.dirty(p);p.teleportTo(l,c.getX()+1,c.getY(),c.getZ()+1,180,0);
    }
    private static void place(ServerLevel l,Map<BlockPos,net.minecraft.world.level.block.state.BlockState> cells){for(var e:cells.entrySet()){l.getChunkAt(e.getKey());l.setBlock(e.getKey(),e.getValue(),2);}}
    private static void automationScene(ServerPlayer p){
        var h=TycoonWorld.home(p);TycoonWorld.enter(p);var l=p.serverLevel();var c=h.center();p.teleportTo(l,c.getX()+1,c.getY(),c.getZ()+1,0,0);h.state.putBoolean("SendHome",false);
        var r=TycoonCare.generate(UUID.randomUUID());automatedResident=r.id;r.n.putString("Status","ACTIVE");r.n.putBoolean("DebugChild",true);r.n.putBoolean("RelationshipInitialized",true);r.n.putInt("VisitCount",2);TycoonDialogue.set(r,.96,.05);var v=new CompoundTag();v.putString("Phase","INSIDE");v.putUUID("Session",UUID.randomUUID());v.putLong("Started",h.clock());v.putLong("EnteredAt",h.clock());v.putLong("LastSeen",h.clock());v.putString("LastDimension",TycoonWorld.KEY.location().toString());v.putLong("LastAt",c.offset(1,0,2).asLong());v.putLong("LeaveAfter",h.clock()+10000);v.putLong("NextExplore",h.clock()+10000);r.n.put("Visit",v);h.residents.put(r.id,r);var child=TycoonContent.NPC.get().create(l);child.configure(h.owner,r.id,false,r.n.getInt("Appearance"));child.setPos(Vec3.atBottomCenterOf(c.offset(1,0,2)));r.n.putUUID("Entity",child.getUUID());l.addFreshEntity(child);h.state.putBoolean("VisitActive",true);TycoonVisitTickets.world(p,c);
        for(var type:List.of(TycoonWorkerType.OTHER_MANAGER,TycoonWorkerType.SOUL_MANAGER)){var id=UUID.randomUUID();var at=type==TycoonWorkerType.OTHER_MANAGER?c.offset(-1,0,2):farm.offset(-3,1,-2);var worker=TycoonAutomationContent.WORKER.get().create(l);worker.configure(h.owner,id,type,5);worker.setPos(Vec3.atBottomCenterOf(at));var row=new CompoundTag();row.putUUID("Id",id);row.putUUID("Owner",h.owner);row.putUUID("Actor",worker.getUUID());row.putString("Type",type.id());row.putInt("Unlocked",5);row.putInt("Operating",5);row.putLong("Area",at.asLong());row.putLong("LastAt",at.asLong());row.putInt("Priority",80);var all=TycoonWorkers.workers(h);all.put(id.toString(),row);h.state.put("Workers",all);l.addFreshEntity(worker);}
        // Supply a genuine paid upgrade: the two original souls plus the first
        // conversion fill Tier3. The fourth soul needs actual new capacity.
        for(int slot=0;slot<p.getInventory().items.size()&&TycoonWarehouse.count(h,TycoonContent.VOID_POWER.get())<128;slot++)if(p.getInventory().getItem(slot).is(TycoonContent.VOID_POWER.get())){if(slot>8){check(p.getInventory().getItem(4).isEmpty(),"QA hotbar transfer would overwrite an item");p.getInventory().setItem(4,p.getInventory().getItem(slot));p.getInventory().setItem(slot,ItemStack.EMPTY);p.getInventory().selected=4;}else p.getInventory().selected=slot;int amount=p.getMainHandItem().getCount();check(TycoonWarehouse.deposit(p,amount).startsWith("Purchased"),"Real worker supply deposit failed");}
        p.getInventory().selected=0;p.connection.send(new net.minecraft.network.protocol.game.ClientboundSetCarriedItemPacket(0));
        check(TycoonWarehouse.count(h,TycoonContent.VOID_POWER.get())>=64,"Farm upgrade has no physical Power budget");
        TycoonPolicies.state(h).putBoolean("conversations",true);TycoonPolicies.state(h).putBoolean("proposals",true);TycoonPolicies.state(h).putBoolean("farmUpgrades",true);TycoonPolicies.state(h).putLong("constructionPowerHour",128);TycoonPolicies.state(h).putLong("farmSoulBudgetHour",30);farmIncomeBefore=h.clock();TycoonWorld.dirty(p);
    }
    private static void seeingStoneScene(ServerPlayer p){var l=p.server.overworld();var at=new BlockPos(120000,180,120000);for(int x=-10;x<=10;x++)for(int z=-3;z<=12;z++){var cell=at.offset(x,0,z);l.getChunkAt(cell);l.setBlock(cell.below(),Blocks.STONE.defaultBlockState(),2);for(int y=0;y<5;y++)l.setBlock(cell.above(y),Blocks.AIR.defaultBlockState(),2);}l.setDayTime(6000);var hostile=net.minecraft.world.entity.EntityType.ZOMBIE.create(l);hostile.setNoAi(true);hostile.setPersistenceRequired();hostile.setItemSlot(net.minecraft.world.entity.EquipmentSlot.HEAD,new ItemStack(Items.IRON_HELMET));hostile.setPos(at.getX()-.7,at.getY(),at.getZ()+6);l.addFreshEntity(hostile);var passive=net.minecraft.world.entity.EntityType.COW.create(l);passive.setNoAi(true);passive.setPersistenceRequired();passive.setPos(at.getX()+.8,at.getY(),at.getZ()+6);l.addFreshEntity(passive);p.teleportTo(l,at.getX(),at.getY(),at.getZ(),0,5);p.getInventory().selected=0;p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(com.coraline.registry.ModItems.SEEING_STONE.get()));p.inventoryMenu.broadcastChanges();}
    private static boolean world(){if(mc.screen instanceof com.coraline.client.TycoonWorldScreen)return true;if(mc.screen instanceof com.coraline.client.TycoonScreen){press("World");press("Dolls / World");return false;}if(age%20==0){var at=TycoonWorld.home(owner()).center().offset(1,0,-1);mc.gameMode.useItemOn(mc.player,InteractionHand.MAIN_HAND,new BlockHitResult(at.getCenter(),Direction.NORTH,at,false));}return false;}
    private static TycoonNpc clientActor(){for(var entity:mc.level.entitiesForRendering())if(entity instanceof TycoonNpc child&&child.getUUID().equals(actor))return child;return null;}
    private static ServerPlayer owner(){return mc.getSingleplayerServer().getPlayerList().getPlayers().get(0);}
    private static void server(int expected,Consumer<ServerPlayer> action){if(pending)return;pending=true;mc.getSingleplayerServer().execute(()->{try{if(stage==expected)action.accept(owner());}catch(Throwable e){failed=e;}finally{pending=false;}});}
    private static void go(int next){stage=next;age=0;}
    private static boolean press(String prefix){if(mc.screen==null)return false;for(var child:mc.screen.children())if(child instanceof Button button&&button.active&&button.visible&&button.getMessage().getString().startsWith(prefix)){button.onPress();return true;}return false;}
    private static void check(boolean value,String message){if(!value)throw new IllegalStateException(message);}
    private static void layout(){var buttons=new ArrayList<AbstractWidget>();for(var child:mc.screen.children())if(child instanceof AbstractWidget widget&&widget.visible)buttons.add(widget);for(int i=0;i<buttons.size();i++){var a=buttons.get(i);check(a.getX()>=0&&a.getY()>=0&&a.getX()+a.getWidth()<=mc.screen.width&&a.getY()+a.getHeight()<=mc.screen.height,"Off-screen control: "+a.getMessage().getString());for(int j=i+1;j<buttons.size();j++){var b=buttons.get(j);check(!(a.getX()<b.getX()+b.getWidth()&&b.getX()<a.getX()+a.getWidth()&&a.getY()<b.getY()+b.getHeight()&&b.getY()<a.getY()+a.getHeight()),"Overlapping controls: "+a.getMessage().getString()+" / "+b.getMessage().getString());}}}
    private static void shot(String name){try{var folder=java.nio.file.Path.of("artwork/tycoon_expansion_qa").toAbsolutePath();java.nio.file.Files.createDirectories(folder);try(var pixels=net.minecraft.client.Screenshot.takeScreenshot(mc.getMainRenderTarget())){pixels.writeToFile(folder.resolve(name+".png"));}}catch(java.io.IOException e){throw new IllegalStateException(e);}}
    private TycoonExpansionVisualCheck(){}
}
